 function socialPurchase(s,buyer,price){
  const id=s.id+':purchase:'+s.cycle+':'+s.sold;
  if(s.social.purchases[id])return;
  const random=tag=>Audience.random(id+':'+tag);
  const reviewed=random('review')<socialRates.review;
  const posted=random('post')<socialRates.post;
  if(s.market?.active?.growthKey&&!reviewed&&!posted)return;
  const experience=Audience.review(s,[{buyer,price,sequence:s.sold}],s.sold);
  const sentiment=experience.stars<=2?'negative':experience.stars>=4&&experience.reason==='satisfied'?'positive':'mixed';
  s.social.purchases[id]={id,productId:s.productId,personaId:buyer.personaId,...socialDate(s),
   stars:experience.stars,sentiment,axis:experience.axis,reason:experience.reason,reviewed,posted};
  if(reviewed){
   const review={...experience,purchaseId:id,week:socialDate(s).week,day:socialDate(s).day,
    feedback:random('review-text')<socialRates.text?experience.feedback:''};
   s.reviews.push(review);
   s.reviewCount=s.reviews.length;
   if(s.reach)Reach.recordReview(s,review);
  }
  if(posted){
   const openings={positive:['Já entrou na minha rotina.','Uma compra que valeu a pena.','Usei e gostei.'],
    mixed:['Depois de experimentar, fiquei dividido.','Tem pontos bons e outros a melhorar.','Minha impressão depois de usar.'],
    negative:['Fiquei decepcionado com a compra.','Esperava uma experiência melhor.','No meu uso, não funcionou bem.']}[sentiment];
   const index=Math.floor(random('post-wording')*openings.length);
   const previous=s.social.posts.at(-1)?.text;
   const text=openings[index]+' '+experience.feedback;
   publish(s,{id:id+':post',purchaseId:id,origin:'consumer',authorId:buyer.id,author:experience.buyer,
    context:experience.profile.context,product:s.name,image:productImage(s),sentiment,
    text:text===previous?openings[(index+1)%openings.length]+' '+experience.feedback:text,
    reactions:Math.floor(random('reactions')*7),comments:random('comment')<.4?['Valeu por contar como foi no uso.']:[]});
  }
 }
